import asyncioimport jsonimport osimport reimport sysimport timeimport uuidfrom collections import dequefrom datetime import datetimefrom typing import Anyimport uvicornfrom fastapi import FastAPI, Requestfrom fastapi.responses import HTMLResponse, StreamingResponsetry:    import winsoundexcept ImportError:    winsound = Noneapp = FastAPI(title="ConnectIoT Local Log Viewer")MAX_LOGS = 5000ORPHAN_MANAGER = "Orphan"logs_buffer: deque[dict[str, Any]] = deque(maxlen=MAX_LOGS)seen_managers: set[str] = set()subscribers: list[asyncio.Queue] = []CTX_REGEX = re.compile(r"\[([a-f0-9]{8})\|")LEVEL_ORDER = {"DEBUG": 1, "INFO": 2, "WARN": 3, "ERROR": 4}DEFAULT_ALARMS: list[dict[str, Any]] = [    {        "id": "error-alarm",        "name": "ERROR ALARM",        "pattern": "",        "min_level": "ERROR",        "enabled": True,        "sound": False,    },]def get_data_dir() -> str:    if getattr(sys, "frozen", False):        return os.path.dirname(sys.executable)    return os.path.dirname(os.path.abspath(__file__))ALARMS_FILE = os.path.join(get_data_dir(), "alarms.json")def load_alarms() -> list[dict[str, Any]]:    if os.path.exists(ALARMS_FILE):        try:            with open(ALARMS_FILE, "r", encoding="utf-8") as f:                data = json.load(f)                if isinstance(data, list):                    return data        except Exception:            pass    save_alarms(DEFAULT_ALARMS)    return [dict(r) for r in DEFAULT_ALARMS]def save_alarms(rules: list[dict[str, Any]]) -> None:    with open(ALARMS_FILE, "w", encoding="utf-8") as f:        json.dump(rules, f, indent=2)alarm_rules: list[dict[str, Any]] = load_alarms()_last_sound_at: float = 0.0def maybe_play_sound(cooldown_sec: float = 3.0) -> None:    global _last_sound_at    if winsound is None:        return    now = time.monotonic()    if now - _last_sound_at >= cooldown_sec:        _last_sound_at = now        try:            winsound.MessageBeep(winsound.MB_ICONEXCLAMATION)        except Exception:            passdef normalize_manager_id(raw_mgr: Any) -> str:    if raw_mgr is None:        return ORPHAN_MANAGER    val = str(raw_mgr).strip()    if not val or val.lower() in ("undefined", "null", "none", "nan"):        return ORPHAN_MANAGER    return valdef extract_manager_id(raw: dict[str, Any]) -> str:    meta = raw.get("meta") if isinstance(raw.get("meta"), dict) else {}    metadata = raw.get("metadata") if isinstance(raw.get("metadata"), dict) else {}    candidate = (        raw.get("managerId")        or raw.get("manager_id")        or meta.get("managerId")        or metadata.get("managerId")    )    return normalize_manager_id(candidate)def get_sorted_managers() -> list[str]:    others = sorted(m for m in seen_managers if m != ORPHAN_MANAGER)    if ORPHAN_MANAGER in seen_managers:        return others + [ORPHAN_MANAGER]    return othersdef evaluate_alarms(entry: dict[str, Any]) -> tuple[list[str], bool]:    """Returns (matching_alarm_names, should_play_sound)."""    alerts: list[str] = []    play_sound = False    msg = entry["message"]    msg_lower = msg.lower()    entry_rank = LEVEL_ORDER.get(entry["level"], 1)    for rule in alarm_rules:        if not rule.get("enabled", True):            continue        min_lvl = str(rule.get("min_level") or "ALL").upper()        if min_lvl != "ALL" and entry_rank < LEVEL_ORDER.get(min_lvl, 1):            continue        pattern = str(rule.get("pattern") or "").strip()        matched = False        if not pattern:            matched = min_lvl != "ALL"        else:            matched = pattern.lower() in msg_lower        if matched:            name = str(rule.get("name") or pattern or "Alarm")            if name not in alerts:                alerts.append(name)            if bool(rule.get("sound", False)):                play_sound = True    return alerts, play_sounddef reevaluate_buffer() -> None:    for item in logs_buffer:        alerts, _ = evaluate_alarms(item)        item["alerts"] = alertsdef normalize_entry(raw: dict[str, Any]) -> dict[str, Any]:    msg = str(raw.get("message") or raw.get("msg") or "")    level = str(raw.get("level", "info")).upper()    if level == "WARNING":        level = "WARN"    ts = raw.get("timestamp")    if not ts:        now = datetime.now()        ts = f"{now.strftime('%Y-%m-%d %H:%M:%S')}.{int(now.microsecond / 1000):03d}"    manager_id = extract_manager_id(raw)    seen_managers.add(manager_id)    ctx_match = CTX_REGEX.search(msg)    context_id = ctx_match.group(1) if ctx_match else None    is_heartbeat = "Subscription Heartbeat" in msg    item = {        "id": len(logs_buffer) + 1,        "ts": str(ts),        "level": level,        "manager_id": manager_id,        "message": msg,        "context_id": context_id,        "is_heartbeat": is_heartbeat,        "raw": raw,    }    alerts, should_sound = evaluate_alarms(item)    item["alerts"] = alerts    item["_play_sound"] = should_sound    return itemasync def broadcast(payload: dict[str, Any]) -> None:    dead: list[asyncio.Queue] = []    for q in subscribers:        try:            q.put_nowait(payload)        except asyncio.QueueFull:            dead.append(q)    for q in dead:        subscribers.remove(q)@app.post("/logs")async def ingest_logs(request: Request):    try:        payload = await request.json()    except Exception:        body = await request.body()        payload = {"message": body.decode("utf-8", errors="replace"), "level": "info"}    entries = payload if isinstance(payload, list) else [payload]    accepted = 0    any_sound = False    for raw in entries:        if isinstance(raw, dict):            item = normalize_entry(raw)        else:            item = normalize_entry({"message": str(raw), "level": "info"})        if item.get("_play_sound"):            any_sound = True        logs_buffer.append(item)        clean_item = {k: v for k, v in item.items() if k != "_play_sound"}        await broadcast({"type": "log", "item": clean_item, "managers": get_sorted_managers()})        accepted += 1    if any_sound:        maybe_play_sound()    return {"status": "ok", "accepted": accepted}@app.get("/api/recent")async def recent_logs(limit: int = 500):    items = [{k: v for k, v in x.items() if k != "_play_sound"} for x in list(logs_buffer)[-limit:]]    return {"items": items, "alarms": alarm_rules, "managers": get_sorted_managers()}@app.get("/stream")async def stream_logs(request: Request):    q: asyncio.Queue = asyncio.Queue(maxsize=500)    subscribers.append(q)    async def event_generator():        try:            while True:                if await request.is_disconnected():                    break                event_payload = await q.get()                yield f"data: {json.dumps(event_payload)}\n\n"        finally:            if q in subscribers:                subscribers.remove(q)    return StreamingResponse(event_generator(), media_type="text/event-stream")@app.get("/api/alarms")async def get_alarms_api():    return {"items": alarm_rules}@app.post("/api/alarms")async def create_alarm_api(request: Request):    body = await request.json()    pattern = str(body.get("pattern") or "").strip()    name = str(body.get("name") or pattern or "Custom Alarm").strip()    min_level = str(body.get("min_level") or "ALL").upper()    if min_level not in ("ALL", "DEBUG", "INFO", "WARN", "ERROR"):        min_level = "ALL"    rule = {        "id": uuid.uuid4().hex[:8],        "name": name,        "pattern": pattern,        "min_level": min_level,        "enabled": bool(body.get("enabled", True)),        "sound": bool(body.get("sound", False)),    }    alarm_rules.append(rule)    save_alarms(alarm_rules)    reevaluate_buffer()    return {"status": "ok", "item": rule}@app.patch("/api/alarms/{rule_id}")async def patch_alarm_api(rule_id: str, request: Request):    body = await request.json()    for rule in alarm_rules:        if rule["id"] == rule_id:            if "name" in body:                rule["name"] = str(body["name"]).strip() or rule["name"]            if "pattern" in body:                rule["pattern"] = str(body["pattern"]).strip()            if "min_level" in body:                lvl = str(body["min_level"]).upper()                if lvl in ("ALL", "DEBUG", "INFO", "WARN", "ERROR"):                    rule["min_level"] = lvl            if "enabled" in body:                rule["enabled"] = bool(body["enabled"])            if "sound" in body:                rule["sound"] = bool(body["sound"])            save_alarms(alarm_rules)            reevaluate_buffer()            return {"status": "ok", "item": rule}    return {"status": "not_found"}@app.delete("/api/alarms/{rule_id}")async def delete_alarm_api(rule_id: str):    global alarm_rules    before = len(alarm_rules)    alarm_rules = [r for r in alarm_rules if r["id"] != rule_id]    if len(alarm_rules) != before:        save_alarms(alarm_rules)        reevaluate_buffer()        return {"status": "ok", "deleted": rule_id}    return {"status": "not_found"}HTML_PAGE = """<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8" /><title>ConnectIoT Log Viewer</title><style>  :root {    --bg: #0f172a; --panel: #1e293b; --border: #334155;    --text: #e2e8f0; --muted: #94a3b8;    --debug: #60a5fa; --info: #34d399; --warn: #fbbf24; --error: #f87171;  }  * { box-sizing: border-box; }  body {    margin: 0;    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;    font-size: 12px;    line-height: 1.25;    background: var(--bg);    color: var(--text);  }  header {    position: sticky; top: 0; z-index: 10;    background: var(--panel); border-bottom: 1px solid var(--border);    padding: 8px 12px; display: flex; flex-wrap: wrap; gap: 8px; align-items: center;  }  input, select, button {    background: var(--bg); color: var(--text); border: 1px solid var(--border);    border-radius: 5px; padding: 4px 8px; font-family: inherit; font-size: 12px;  }  button { cursor: pointer; }  button:hover { border-color: #64748b; }  button.active { background: #2563eb; border-color: #3b82f6; color: #fff; }  button.danger { border-color: rgba(248,113,113,0.45); color: #fca5a5; }  button.danger:hover { background: rgba(248,113,113,0.16); }  .stats { margin-left: auto; color: var(--muted); font-size: 12px; }  #log-list { padding: 4px 10px 32px; }  .row {    display: grid;    grid-template-columns: 96px 142px 52px 84px 1fr;    gap: 6px;    padding: 1px 4px;    border-bottom: 1px solid rgba(51,65,85,0.28);    align-items: center;  }  .row:hover { background: rgba(255,255,255,0.03); }  .row.has-alert { background: rgba(248, 113, 113, 0.08); }  .ts { color: var(--muted); white-space: nowrap; font-size: 11px; }  .mgr-tag {    border-radius: 3px; padding: 0 5px; font-size: 11px;    background: rgba(56,189,248,0.14); color: #7dd3fc;    border: 1px solid rgba(56,189,248,0.3);    cursor: pointer; text-align: center;    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;  }  .mgr-tag.orphan {    background: rgba(148,163,184,0.12); color: var(--muted);    border-color: rgba(148,163,184,0.28); font-style: italic;  }  .lvl-DEBUG { color: var(--debug); }  .lvl-INFO { color: var(--info); }  .lvl-WARN { color: var(--warn); font-weight: 600; }  .lvl-ERROR { color: var(--error); font-weight: 700; }  .ctx {    border-radius: 3px; padding: 0 5px; font-size: 11px;    background: rgba(148,163,184,0.14); cursor: pointer;    text-align: center; white-space: nowrap;  }  .msg { white-space: pre-wrap; word-break: break-word; }  .badge {    display: inline-block; margin-left: 6px; padding: 0 6px;    border-radius: 999px; font-size: 10px; cursor: pointer;    background: rgba(251,191,36,0.18); color: #fde68a; border: 1px solid rgba(251,191,36,0.4);  }  .badge.err { background: rgba(248,113,113,0.2); color: #fecaca; border-color: rgba(248,113,113,0.45); }  /* Modal */  .modal-backdrop {    display: none; position: fixed; inset: 0; z-index: 50;    background: rgba(2, 6, 23, 0.72); align-items: center; justify-content: center; padding: 16px;  }  .modal-backdrop.open { display: flex; }  .modal {    width: 100%; max-width: 760px; max-height: 86vh; overflow: auto;    background: var(--panel); border: 1px solid var(--border); border-radius: 8px;    padding: 16px; box-shadow: 0 20px 50px rgba(0,0,0,0.5);  }  .modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }  .modal-header h2 { margin: 0; font-size: 15px; }  .alarm-form {    display: grid; grid-template-columns: 1fr 1.4fr 110px auto auto auto;    gap: 8px; align-items: center; padding-bottom: 14px; border-bottom: 1px solid var(--border);  }  .check-label { display: inline-flex; align-items: center; gap: 4px; color: var(--muted); font-size: 11px; user-select: none; }  .alarm-list { margin-top: 12px; display: flex; flex-direction: column; gap: 8px; }  .alarm-card {    display: grid; grid-template-columns: auto 1fr auto auto; gap: 10px; align-items: center;    background: var(--bg); border: 1px solid var(--border); border-radius: 6px; padding: 8px 10px;  }  .alarm-card.disabled { opacity: 0.55; }  .alarm-meta { color: var(--muted); font-size: 11px; margin-top: 2px; }  code { background: rgba(148,163,184,0.12); padding: 1px 5px; border-radius: 4px; color: #f8fafc; }</style></head><body><header>  <strong>ConnectIoT Viewer</strong>  <select id="managerFilter" title="Filter logs by Manager ID">    <option value="ALL">All Managers</option>  </select>  <select id="levelFilter">    <option value="ALL">All Levels</option>    <option value="DEBUG">DEBUG+</option>    <option value="INFO">INFO+</option>    <option value="WARN">WARN+</option>    <option value="ERROR">ERROR only</option>  </select>  <select id="alarmFilter" title="Filter log lines by alarm tag">    <option value="ALL">All logs</option>    <option value="ANY">Any Alarm</option>  </select>  <input id="searchBox" type="text" placeholder="Filter text, manager, or context ID..." style="width: 240px;" />  <button id="hideHeartbeats" class="active" title="Hide Subscription Heartbeat lines">Hide Heartbeats</button>  <button id="openAlarmsBtn">Alarms</button>  <button id="autoScrollBtn" class="active" title="Auto-scrolls to newest logs; turns off automatically when you scroll up">Auto-Scroll: ON</button>  <button id="clearBtn">Clear View</button>  <div class="stats" id="stats">0 shown / 0 total | Alarms: 0</div></header><div id="log-list"></div><div class="modal-backdrop" id="alarmsModal">  <div class="modal">    <div class="modal-header">      <h2>Alarm Rules (Search-String Triggers)</h2>      <button id="closeAlarmsBtn">Close</button>    </div>    <form class="alarm-form" id="alarmForm">      <input id="alarmName" type="text" placeholder="Alarm name (optional)" />      <input id="alarmPattern" type="text" placeholder="Search string (e.g. Lost inputs:)" />      <select id="alarmLevel">        <option value="ALL">Level: ALL</option>        <option value="DEBUG">DEBUG+</option>        <option value="INFO">INFO+</option>        <option value="WARN">WARN+</option>        <option value="ERROR">ERROR</option>      </select>      <label class="check-label"><input id="alarmEnabled" type="checkbox" checked /> Active</label>      <label class="check-label"><input id="alarmSound" type="checkbox" /> Sound</label>      <button type="submit" class="active">Add</button>    </form>    <div class="alarm-list" id="alarmList"></div>  </div></div><script>const LEVEL_RANK = { DEBUG: 1, INFO: 2, WARN: 3, ERROR: 4 };const CTX_PALETTE = ["#f472b6", "#22d3ee", "#fb923c", "#a78bfa", "#4ade80", "#facc15"];const ctxColorMap = new Map();let allItems = [];let knownManagers = [];let alarmRules = [];let autoScroll = true;let programmaticScroll = false;let hideHeartbeats = true;let totalCount = 0;let alarmCount = 0;const listEl = document.getElementById("log-list");const statsEl = document.getElementById("stats");const managerEl = document.getElementById("managerFilter");const levelEl = document.getElementById("levelFilter");const alarmFilterEl = document.getElementById("alarmFilter");const searchEl = document.getElementById("searchBox");const autoScrollBtn = document.getElementById("autoScrollBtn");const modalEl = document.getElementById("alarmsModal");const alarmListEl = document.getElementById("alarmList");function setAutoScrollState(enabled) {  autoScroll = enabled;  autoScrollBtn.classList.toggle("active", autoScroll);  autoScrollBtn.textContent = autoScroll ? "Auto-Scroll: ON" : "Auto-Scroll: OFF";}function isNearBottom() {  return (window.innerHeight + window.scrollY) >= (document.body.scrollHeight - 40);}function scrollToBottomNow() {  programmaticScroll = true;  window.scrollTo(0, document.body.scrollHeight);  requestAnimationFrame(() => {    programmaticScroll = false;  });}window.addEventListener("scroll", () => {  if (programmaticScroll) return;  const nearBottom = isNearBottom();  if (!nearBottom && autoScroll) {    setAutoScrollState(false);  } else if (nearBottom && !autoScroll) {    setAutoScrollState(true);  }}, { passive: true });function getCtxColor(ctx) {  if (!ctxColorMap.has(ctx)) {    ctxColorMap.set(ctx, CTX_PALETTE[ctxColorMap.size % CTX_PALETTE.length]);  }  return ctxColorMap.get(ctx);}function escapeHtml(s) {  return String(s ?? "").replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));}function syncManagerOptions(managers) {  const prev = managerEl.value || "ALL";  const list = Array.isArray(managers) ? managers : [];  knownManagers = list;  const opts = [`<option value="ALL">All Managers</option>`];  for (const m of list) {    if (m === "Orphan") {      opts.push(`<option value="Orphan">Orphan (No Manager)</option>`);    } else {      opts.push(`<option value="${escapeHtml(m)}">${escapeHtml(m)}</option>`);    }  }  managerEl.innerHTML = opts.join("");  if (prev === "ALL" || list.includes(prev)) {    managerEl.value = prev;  } else {    managerEl.value = "ALL";  }}function matchesFilter(item) {  if (hideHeartbeats && item.is_heartbeat) return false;  const selectedMgr = managerEl.value || "ALL";  const itemMgr = item.manager_id || "Orphan";  if (selectedMgr !== "ALL" && itemMgr !== selectedMgr) return false;  const selectedLevel = levelEl.value;  if (selectedLevel !== "ALL") {    const minRank = LEVEL_RANK[selectedLevel] || 1;    const itemRank = LEVEL_RANK[item.level] || 1;    if (selectedLevel === "ERROR" && item.level !== "ERROR") return false;    if (selectedLevel !== "ERROR" && itemRank < minRank) return false;  }  const selectedAlarm = alarmFilterEl.value;  if (selectedAlarm !== "ALL") {    const itemAlerts = item.alerts || [];    if (selectedAlarm === "ANY") {      if (itemAlerts.length === 0) return false;    } else if (!itemAlerts.includes(selectedAlarm)) {      return false;    }  }  const q = searchEl.value.trim().toLowerCase();  if (q) {    const hay = `${item.message} ${itemMgr} ${item.context_id || ""} ${item.level}`.toLowerCase();    if (!hay.includes(q)) return false;  }  return true;}function renderRow(item) {  const row = document.createElement("div");  const hasAlerts = item.alerts && item.alerts.length > 0;  row.className = "row" + (hasAlerts ? " has-alert" : "");  const mgr = item.manager_id || "Orphan";  const isOrphan = mgr === "Orphan";  const mgrHtml = `<span class="mgr-tag${isOrphan ? " orphan" : ""}" title="Click to filter by ${escapeHtml(mgr)}" onclick="setManagerFilter(${JSON.stringify(mgr)})">${escapeHtml(mgr)}</span>`;  const ctxHtml = item.context_id    ? `<span class="ctx" style="color:${getCtxColor(item.context_id)}" title="Click to filter context ${item.context_id}" onclick="setSearch('${item.context_id}')">${item.context_id}</span>`    : `<span></span>`;  const badgesHtml = hasAlerts    ? item.alerts.map(a => `<span class="badge ${item.level === "ERROR" ? "err" : ""}" title="Click to filter by ${escapeHtml(a)}" onclick="setAlarmFilter(${JSON.stringify(a)})">${escapeHtml(a)}</span>`).join("")    : "";  row.innerHTML = `    <span class="ts" title="${escapeHtml(item.ts)}">${escapeHtml(item.ts)}</span>    ${mgrHtml}    <span class="lvl-${item.level}">${escapeHtml(item.level)}</span>    ${ctxHtml}    <span class="msg">${escapeHtml(item.message)}${badgesHtml}</span>  `;  return row;}function countVisibleRows() {  return listEl.children.length;}function rerender() {  listEl.innerHTML = "";  let shown = 0;  alarmCount = 0;  for (const item of allItems) {    if (item.alerts && item.alerts.length > 0) alarmCount++;    if (matchesFilter(item)) {      listEl.appendChild(renderRow(item));      shown++;    }  }  statsEl.textContent = `${shown} shown / ${totalCount} total | Alarms: ${alarmCount}`;  if (autoScroll) {    scrollToBottomNow();  }}function appendItem(item, managers = null) {  if (Array.isArray(managers)) {    syncManagerOptions(managers);  } else if (item.manager_id && !knownManagers.includes(item.manager_id)) {    syncManagerOptions([...knownManagers, item.manager_id]);  }  totalCount++;  if (item.alerts && item.alerts.length > 0) alarmCount++;  allItems.push(item);  if (allItems.length > 3000) allItems.shift();  if (matchesFilter(item)) {    listEl.appendChild(renderRow(item));    if (autoScroll) {      scrollToBottomNow();    }  }  statsEl.textContent = `${countVisibleRows()} shown / ${totalCount} total | Alarms: ${alarmCount}`;}async function refreshRecentAndReevaluate() {  const res = await fetch("/api/recent?limit=500");  const data = await res.json();  syncManagerOptions(data.managers || []);  allItems = data.items || [];  totalCount = allItems.length;  rerender();}function syncAlarmFilterOptions() {  const prev = alarmFilterEl.value;  const names = [...new Set(alarmRules.map(r => r.name).filter(Boolean))];  alarmFilterEl.innerHTML =    `<option value="ALL">All logs</option>` +    `<option value="ANY">Any Alarm</option>` +    names.map(n => `<option value="${escapeHtml(n)}">${escapeHtml(n)}</option>`).join("");  if (prev === "ALL" || prev === "ANY" || names.includes(prev)) {    alarmFilterEl.value = prev;  } else {    alarmFilterEl.value = "ALL";  }}function renderAlarmRules() {  alarmListEl.innerHTML = "";  if (!alarmRules.length) {    alarmListEl.innerHTML = `<div style="color:var(--muted)">No alarm rules configured yet.</div>`;    syncAlarmFilterOptions();    return;  }  for (const rule of alarmRules) {    const card = document.createElement("div");    card.className = "alarm-card" + (rule.enabled ? "" : " disabled");    const patternDisplay = rule.pattern ? `<code>${escapeHtml(rule.pattern)}</code>` : `<em>(any message)</em>`;    const soundLabel = rule.sound ? " | Sound: ON" : "";    card.innerHTML = `      <input type="checkbox" ${rule.enabled ? "checked" : ""} title="Activate or deactivate rule" onchange="toggleAlarm('${rule.id}', this.checked)" />      <div>        <strong>${escapeHtml(rule.name)}</strong>        <div class="alarm-meta">Search: ${patternDisplay} | Min Level: <code>${escapeHtml(rule.min_level)}</code>${soundLabel}</div>      </div>      <button onclick="toggleSound('${rule.id}', ${!rule.sound})">${rule.sound ? "Mute Sound" : "Sound Off"}</button>      <button class="danger" onclick="deleteAlarm('${rule.id}')">Delete</button>    `;    alarmListEl.appendChild(card);  }  syncAlarmFilterOptions();}async function loadAlarms() {  const res = await fetch("/api/alarms");  const data = await res.json();  alarmRules = data.items || [];  renderAlarmRules();}window.toggleAlarm = async function(id, enabled) {  await fetch(`/api/alarms/${id}`, {    method: "PATCH",    headers: { "Content-Type": "application/json" },    body: JSON.stringify({ enabled }),  });  await loadAlarms();  await refreshRecentAndReevaluate();};window.toggleSound = async function(id, sound) {  await fetch(`/api/alarms/${id}`, {    method: "PATCH",    headers: { "Content-Type": "application/json" },    body: JSON.stringify({ sound }),  });  await loadAlarms();};window.deleteAlarm = async function(id) {  await fetch(`/api/alarms/${id}`, { method: "DELETE" });  await loadAlarms();  await refreshRecentAndReevaluate();};document.getElementById("alarmForm").addEventListener("submit", async (e) => {  e.preventDefault();  const name = document.getElementById("alarmName").value.trim();  const pattern = document.getElementById("alarmPattern").value.trim();  const min_level = document.getElementById("alarmLevel").value;  const enabled = document.getElementById("alarmEnabled").checked;  const sound = document.getElementById("alarmSound").checked;  if (!pattern && min_level === "ALL") {    alert("Enter a search string or choose a minimum level.");    return;  }  await fetch("/api/alarms", {    method: "POST",    headers: { "Content-Type": "application/json" },    body: JSON.stringify({ name, pattern, min_level, enabled, sound }),  });  document.getElementById("alarmName").value = "";  document.getElementById("alarmPattern").value = "";  document.getElementById("alarmSound").checked = false;  document.getElementById("alarmEnabled").checked = true;  await loadAlarms();  await refreshRecentAndReevaluate();});document.getElementById("openAlarmsBtn").addEventListener("click", async () => {  await loadAlarms();  modalEl.classList.add("open");});document.getElementById("closeAlarmsBtn").addEventListener("click", () => {  modalEl.classList.remove("open");});modalEl.addEventListener("click", (e) => {  if (e.target === modalEl) modalEl.classList.remove("open");});window.setManagerFilter = function(mgr) {  managerEl.value = managerEl.value === mgr ? "ALL" : mgr;  rerender();};window.setSearch = function(val) {  searchEl.value = val;  rerender();};window.setAlarmFilter = function(alarmName) {  alarmFilterEl.value = alarmFilterEl.value === alarmName ? "ALL" : alarmName;  rerender();};managerEl.addEventListener("change", rerender);levelEl.addEventListener("change", rerender);alarmFilterEl.addEventListener("change", rerender);searchEl.addEventListener("input", rerender);document.getElementById("hideHeartbeats").addEventListener("click", (e) => {  hideHeartbeats = !hideHeartbeats;  e.target.classList.toggle("active", hideHeartbeats);  rerender();});autoScrollBtn.addEventListener("click", () => {  const nextState = !autoScroll;  setAutoScrollState(nextState);  if (nextState) {    scrollToBottomNow();  }});document.getElementById("clearBtn").addEventListener("click", () => {  listEl.innerHTML = "";  allItems = [];  totalCount = 0;  alarmCount = 0;  statsEl.textContent = "0 shown / 0 total | Alarms: 0";});async function init() {  await loadAlarms();  const res = await fetch("/api/recent?limit=300");  const data = await res.json();  syncManagerOptions(data.managers || []);  for (const item of (data.items || [])) {    appendItem(item, data.managers || []);  }  const es = new EventSource("/stream");  es.onmessage = (ev) => {    const msg = JSON.parse(ev.data);    if (msg && msg.type === "log" && msg.item) {      appendItem(msg.item, msg.managers);    } else if (msg) {      appendItem(msg);    }  };}init();</script></body></html>"""@app.get("/", response_class=HTMLResponse)async def index():    return HTML_PAGEif __name__ == "__main__":    uvicorn.run(app, host="0.0.0.0", port=8000, log_level="info")